function canPlantAll(pots: number[], k: number): boolean {
  const n = pots.length;
  let fit = 0, i = 0;
  while (i < n) {
    if (pots[i] === 1) { i++; continue; }
    let j = i;
    while (j < n && pots[j] === 0) j++;
    const len = j - i;
    const openEnds = (i === 0 ? 1 : 0) + (j === n ? 1 : 0);
    // each open end acts like one extra empty pot beyond the row
    fit += Math.floor((len - 1 + openEnds) / 2);
    i = j;
  }
  return fit >= k;
}

