        n, fit, i = len(pots), 0, 0
        while i < n:
            if pots[i] == 1:
                i += 1
                continue
            j = i
            while j < n and pots[j] == 0:
                j += 1
            open_ends = (i == 0) + (j == n)
            fit += (j - i - 1 + open_ends) // 2
            i = j
        return fit >= k

