function canPlantAll(pots: number[], k: number): boolean {
  const row = pots.slice();
  let count = 0;
  for (let i = 0; i < row.length && count < k; i++) {
    if (row[i] === 0 && (i === 0 || row[i - 1] === 0) && (i === row.length - 1 || row[i + 1] === 0)) {
      row[i] = 1;
      count++;
    }
  }
  return count >= k;
}

